const SCRIPT = "\n  (function () {\n    var root = document.querySelector(\".cpc-walk-root\");\n    if (!root) return;\n    var reduce = window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n    if (reduce) return; // base state = step 1 visible, no cycling\n\n    var steps = [].slice.call(root.querySelectorAll(\".step\"));\n    var panels = [].slice.call(root.querySelectorAll(\".wpanel\"));\n    var navs = [];\n    for (var i = 0; i < 4; i++) navs.push(root.querySelector(\".nav.n\" + i));\n    var DUR = 4200;\n    var cur = 0, timer = null;\n\n    function paint(n) {\n      cur = n;\n      steps.forEach(function (s, i) { s.setAttribute(\"aria-current\", String(i === n)); });\n      panels.forEach(function (p, i) { p.classList.toggle(\"active\", i === n); });\n      navs.forEach(function (nv, i) { if (nv) nv.classList.toggle(\"on\", i === n); });\n    }\n    function next() { paint((cur + 1) % 4); }\n    function run() { stop(); timer = setInterval(next, DUR); }\n    function stop() { if (timer) { clearInterval(timer); timer = null; } }\n\n    steps.forEach(function (s, i) {\n      s.addEventListener(\"click\", function () { paint(i); run(); });\n    });\n\n    root.style.setProperty(\"--dur\", DUR + \"ms\");\n    paint(0);\n\n    var started = false;\n    if (\"IntersectionObserver\" in window) {\n      var io = new IntersectionObserver(function (es) {\n        es.forEach(function (e) {\n          if (e.isIntersecting) { if (!started) { started = true; } run(); }\n          else stop();\n        });\n      }, { threshold: 0.3 });\n      io.observe(root);\n    } else { run(); }\n  })();\n";

export default function Walkthrough() {
  const ref = useRef<HTMLDivElement>(null);
  const ran = useRef(false);
  useEffect(() => {
    if (ran.current) return;
    ran.current = true;
    try { new Function(SCRIPT)(); } catch (e) { console.error("Walkthrough demo:", e); }
  }, []);
  return (
    <div ref={ref} className="cpc-walk"
      dangerouslySetInnerHTML={{ __html: "<style>" + CSS + "</style>" + MARKUP }} />
  );
}
